import * as T from './assets/vendor/three.module.js';import {crossingActive,crossingCenter} from './crossings.js?v=78';
export function segmentHitsFootprint(a,b,width,depth){let lo=0,hi=1;for(const [index,half]of[[0,width/2],[1,depth/2]]){const d=b[index]-a[index];if(Math.abs(d)<1e-8){if(Math.abs(a[index])<half)continue;return false;}let x=(-half-a[index])/d,y=(half-a[index])/d;if(x>y)[x,y]=[y,x];lo=Math.max(lo,x);hi=Math.min(hi,y);if(lo>hi)return false;}return true;}
export function roadHeightOffset(bridge,railDeck=0){return bridge&&railDeck<1.3?6:-.1;}
export function roadPath(points){let length=0;const distances=[0];for(let i=1;i<points.length;i++){length+=Math.hypot(points[i][0]-points[i-1][0],points[i][1]-points[i-1][1]);distances.push(length);}return {points,distances,length};}
export function sampleRoad(path,distance){let i=1;while(i<path.distances.length-1&&path.distances[i]<distance)i++;const a=path.points[i-1],b=path.points[i],f=T.MathUtils.clamp((distance-path.distances[i-1])/Math.max(.001,path.distances[i]-path.distances[i-1]),0,1);return {x:a[0]+(b[0]-a[0])*f,z:a[1]+(b[1]-a[1])*f,dx:(b[0]-a[0])/Math.max(.001,path.distances[i]-path.distances[i-1]),dz:(b[1]-a[1])/Math.max(.001,path.distances[i]-path.distances[i-1])};}
export function holdAtCrossing(distance,next,stop,active,direction=1){if(!active)return next;const line=stop-direction*7;if(direction>0&&distance<=line&&next>line)return line;if(direction<0&&distance>=line&&next<line)return line;return next;}
export class RoadScenery{
 constructor(world){this.world=world;this.chunks=new Map();this.box=new T.BoxGeometry(1,1,1);this.wheel=new T.CylinderGeometry(.29,.29,.16,8);this.wheel.rotateZ(Math.PI/2);this.materials=new Map();this.roads=world.route?.roads?.length?world.route.roads:(world.route?.roadsBelow??[]).map(r=>({s:r.s,width:r.width,points:[[r.x-r.dx*49,r.z-r.dz*49],[r.x+r.dx*49,r.z+r.dz*49]],source:'OpenStreetMap underpass'}));this.crossings=(world.route?.structures??world.routeStructures?.structures??[]).filter(c=>c.kind==='crossing');}
 mat(color){if(!this.materials.has(color))this.materials.set(color,new T.MeshStandardMaterial({color,roughness:.86}));return this.materials.get(color);}
 build(index){const group=new T.Group(),cars=[],start=index*240,end=start+240,world=this.world;
  // Use surveyed road polylines. A mapped level crossing also defines a short road approach.
  const rows=this.roads.filter(r=>r.s>=start&&r.s<end).map(r=>({...r}));for(const c of this.crossings){const s=crossingCenter(c);if(s<start||s>=end)continue;const a=world.frame(s,-65).p,b=world.frame(s,65).p;if(!rows.some(r=>Math.abs(r.s-s)<12))rows.push({s,points:[[a.x,-a.z],[b.x,-b.z]],width:5.5,crossing:c,source:'crossing approach'});}
  for(const row of rows){const path=roadPath(row.points);if(path.length<10)continue;const ground=(world.point?.(row.s)??world.frame(row.s).p).y+roadHeightOffset(row.bridge,world.deckHeight?.(row.s)??0),positions=[],uv=[],indices=[];
   for(let i=1;i<row.points.length;i++){const a=row.points[i-1],b=row.points[i],len=Math.hypot(b[0]-a[0],b[1]-a[1]);if(len<.1)continue;const nx=-(b[1]-a[1])/len*(row.width??6)/2,nz=(b[0]-a[0])/len*(row.width??6)/2,k=positions.length/3;for(const [x,z]of[[a[0]+nx,a[1]+nz],[a[0]-nx,a[1]-nz],[b[0]+nx,b[1]+nz],[b[0]-nx,b[1]-nz]]){positions.push(x,ground,-z);uv.push(x/4,z/4);}indices.push(k,k+1,k+2,k+1,k+3,k+2);}
   const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(positions,3));geo.setAttribute('uv',new T.Float32BufferAttribute(uv,2));geo.setIndex(indices);geo.computeVertexNormals();const road=new T.Mesh(geo,world.mat?.('#565b5b')??this.mat('#555858'));road.material.side=T.DoubleSide;group.add(road);
   if(!row.bridge&&!row.crossing){for(const c of this.crossings){const cs=crossingCenter(c);if(Math.abs(cs-row.s)>path.length+100)continue;const point=world.frame(cs,world.driveOffset?.(cs)??0).p;let best={distance:Infinity,along:0};for(let i=1;i<path.points.length;i++){const a=path.points[i-1],b=path.points[i],dx=b[0]-a[0],dz=b[1]-a[1],t=T.MathUtils.clamp(((point.x-a[0])*dx+(-point.z-a[1])*dz)/Math.max(.001,dx*dx+dz*dz),0,1),distance=Math.hypot(point.x-a[0]-t*dx,-point.z-a[1]-t*dz);if(distance<best.distance)best={distance,along:path.distances[i-1]+t*(path.distances[i]-path.distances[i-1])};}if(best.distance<(row.width??6)/2+1){row.crossing=c;row.stopAt=best.along;break;}}}
   if(path.length<80||cars.length>=(world.quality==='light'?1:3))continue;const car=new T.Group(),color=['#deded6','#38556d','#a34535','#999e9b','#c4b58f'][Math.abs(Math.round(row.s))%5];const part=(w,h,d,x,y,z,c)=>{const mesh=new T.Mesh(this.box,this.mat(c));mesh.scale.set(w,h,d);mesh.position.set(x,y,z);mesh.userData.shadowCaster=true;car.add(mesh);};part(1.7,.55,4,0,.65,0,color);part(1.5,.65,2.1,0,1.2,-.1,color);part(1.51,.42,1.7,0,1.3,-.1,'#283b45');part(1.3,.25,.04,0,.8,2.01,'#eadfb1');for(const x of[-.85,.85])for(const z of[-1.25,1.25]){const mesh=new T.Mesh(this.wheel,this.mat('#242728'));mesh.position.set(x,.35,z);car.add(mesh);}group.add(car);cars.push({group:car,path,row,ground,distance:path.length*.3,direction:Math.round(row.s)%2?-1:1});
  }
  if(!world.route){const near=world.stations?.reduce((n,st)=>Math.min(n,Math.abs(st.s-(start+120))),Infinity);if(near<550){const positions=[],uv=[],idx=[];for(let s=start,i=0;s<=end;s+=10,i++){const f=world.frame(s);for(const x of[-110,110]){positions.push(f.p.x+f.right.x*x,f.p.y-.105,f.p.z+f.right.z*x);uv.push((f.p.x+f.right.x*x)/7,(f.p.z+f.right.z*x)/7);}if(i){const k=i*2;idx.push(k-2,k-1,k,k-1,k+1,k);}}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(positions,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(idx);g.computeVertexNormals();group.add(new T.Mesh(g,this.mat('#999b96')));}}
  world.scene.add(group);world.atmosphere?.prepare(group);return {group,cars};
 }
 buildingClear(s,x,width,depth){const f=this.world.frame(s,x);for(const road of this.roads){if(Math.abs(road.s-s)>450)continue;const points=road.points.map(([px,pz])=>{const dx=px-f.p.x,dz=-pz-f.p.z;return [dx*f.right.x+dz*f.right.z,dx*f.dir.x+dz*f.dir.z];});for(let i=1;i<points.length;i++)if(segmentHitsFootprint(points[i-1],points[i],width+(road.width??6)+1,depth+(road.width??6)+1))return false;}return true;}
 update(s,speed,dt,focus=s){const index=Math.floor(focus/240),world=this.world;for(let i=index-2;i<=index+2;i++)if(!this.chunks.has(i))this.chunks.set(i,this.build(i));for(const [i,item]of this.chunks){if(Math.abs(i-index)>2){world.scene.remove(item.group);item.group.traverse(o=>{if(o.geometry&&o.geometry!==this.box&&o.geometry!==this.wheel)o.geometry.dispose();});this.chunks.delete(i);continue;}for(const car of item.cars){let next=car.distance+dt*8.3*car.direction;if(next<0)next=car.path.length;if(next>car.path.length)next=0;if(car.row.crossing)next=holdAtCrossing(car.distance,next,car.row.stopAt??car.path.length/2,crossingActive(car.row.crossing,s,speed,(world.playerTrain?.count??2)*20),car.direction);car.distance=next;const p=sampleRoad(car.path,next),dir=car.direction;car.group.position.set(p.x-p.dz*1.15*dir,car.ground,-p.z-p.dx*1.15*dir);car.group.rotation.y=Math.atan2(p.dx*dir,-p.dz*dir);car.group.visible=next>4&&next<car.path.length-4;}}
 }
 dispose(){for(const item of this.chunks.values()){this.world.scene.remove(item.group);item.group.traverse(o=>{if(o.geometry&&o.geometry!==this.box&&o.geometry!==this.wheel)o.geometry.dispose();});}for(const m of this.materials.values())m.dispose();this.box.dispose();this.wheel.dispose();this.chunks.clear();}
}
